import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Handl SDK Generator — JVM Backend — design detail","description":"","frontmatter":{"title":"Handl SDK Generator — JVM Backend — design detail","type":"design","date":"2026-10-28T00:00:00.000Z","updated":"2026-10-29T00:00:00.000Z","refs":["ADR-0111"]},"headers":[],"relativePath":"c/project/design/0111-handl-sdkgen-jvm.md","filePath":"vendored/c/project/design/0111-handl-sdkgen-jvm.md"}`),a={name:`c/project/design/0111-handl-sdkgen-jvm.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-sdk-generator-—-jvm-backend-—-design-detail" tabindex="-1">Handl SDK Generator — JVM Backend — design detail <a class="header-anchor" href="#handl-sdk-generator-—-jvm-backend-—-design-detail" aria-label="Permalink to “Handl SDK Generator — JVM Backend — design detail”">​</a></h1><p>Moved verbatim from ADR-0111 (ADR-0161 size budget). The ADR carries the rules; this page carries the context, tables, phases and trade-offs.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><a href="./0107-handl-sdk-generator.html">ADR-0107 — Handl SDK Generator</a> established a backend-agnostic IR (<code>SdkgenModule</code>) and a port-adapter emitter architecture. The first concrete backend is C / libclang. The next high-priority backend is the JVM, which lets Handl call Java libraries and native Java classes through JNI.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Add a <code>plugin-sdkgen-backend-jvm</code> crate that parses Java class / method signatures (directly or from <code>.class</code> / <code>.jar</code> metadata) and produces <code>SdkgenModule</code> records.</p><ul><li>The backend may start by consuming a list of Java method signatures or a reflection dump; later it can read <code>.class</code> files or use a lightweight parser.</li><li>The <code>client_package</code> for the generated adapter is <code>jvm</code>.</li><li>The adapter uses <code>jvm.call</code> / <code>jvm.exception</code> primitives (a new <code>jvm</code> client package similar to <code>ffi</code>) to invoke methods and translate exceptions into <code>Result&lt;_, JvmException&gt;</code>.</li><li>Map common Java types to Handl types: <ul><li><code>int</code> / <code>Integer</code> → <code>Int</code> (<code>i32</code>)</li><li><code>long</code> / <code>Long</code> → <code>Int</code> (<code>i64</code>)</li><li><code>double</code> / <code>Double</code> → <code>Float</code> (<code>f64</code>)</li><li><code>String</code> → <code>String</code> (<code>jstring</code>)</li><li><code>byte[]</code> / <code>ByteBuffer</code> → <code>Bytes</code> (<code>jbyte_array</code>)</li><li>Object references → <code>Handle</code> (<code>jobject</code>)</li><li><code>void</code> → <code>()</code></li></ul></li><li>Support class-name to package mapping, method overloads via name mangling, and static vs instance method dispatch.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Handl can consume the huge ecosystem of JVM libraries.</li><li>A <code>jvm</code> client package must be designed and implemented, paralleling <code>ffi</code>.</li><li>Overloaded Java methods require a name-mangling scheme in the port.</li><li>This backend is higher priority than Bukkit / Spigot / Paper (ADR-0112) and Windows / macOS C support (ADR-0110), because it is a prerequisite for the Minecraft server backends.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="./0107-handl-sdk-generator.html">ADR-0107 — Handl SDK Generator</a></li><li><code>crates/plugin-sdkgen</code></li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};